def encrypt(s, k):
    out = ""
    for ch in s:
        if ch.islower():
            out += chr((ord(ch) - 97 + k) % 26 + 97)
        elif ch.isupper():
            out += chr((ord(ch) - 65 + k) % 26 + 65)
        else:
            out += ch
    return out

